configs.snippet:
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "DenyOutsideApprovedRegions",
      "Effect": "Deny",
      "Action": "*",
      "Resource": "*",
      "Condition": {
        "StringNotEquals": {
          "aws:RequestedRegion": ["eu-west-1", "eu-central-1"]
        }
      }
    }
  ]
}

{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AllowVendorAssumeWithExternalId",
      "Effect": "Allow",
      "Principal": {"AWS": "arn:aws:iam::111122223333:root"},
      "Action": "sts:AssumeRole",
      "Condition": {"StringEquals": {"sts:ExternalId": "example-external-id"}}
    }
  ]
}

{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "MaxReadOnlyDataAccess",
      "Effect": "Allow",
      "Action": ["s3:GetObject", "s3:ListBucket", "kms:Decrypt"],
      "Resource": [
        "arn:aws:s3:::example-app-data",
        "arn:aws:s3:::example-app-data/*",
        "arn:aws:kms:eu-west-1:111122223333:key/example-key-id"
      ]
    }
  ]
}

{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "DenyOutsideApprovedRegions",
      "Effect": "Deny",
      "Action": "*",
      "Resource": "*",
      "Condition": {
        "StringNotEquals": {"aws:RequestedRegion": ["eu-west-1"]}
      }
    },
    {
      "Sid": "ProtectSecurityTelemetry",
      "Effect": "Deny",
      "Action": [
        "cloudtrail:StopLogging",
        "cloudtrail:DeleteTrail",
        "guardduty:DeleteDetector"
      ],
      "Resource": "*"
    }
  ]
}

{
  "bindings": [
    {
      "role": "roles/storage.objectViewer",
      "members": ["group:analysts@example.com"],
      "condition": {
        "title": "BusinessHoursBerlin",
        "description": "Read access only during staffed hours",
        "expression": "request.time.getHours('Europe/Berlin') >= 8 && request.time.getHours('Europe/Berlin') < 18"
      }
    }
  ]
}

{
  "BlockPublicAcls": true,
  "IgnorePublicAcls": true,
  "BlockPublicPolicy": true,
  "RestrictPublicBuckets": true
}

{
  "GroupName": "app-web",
  "Description": "HTTPS from the internal load balancer subnet only",
  "VpcId": "vpc-0example",
  "IpPermissions": [
    {
      "IpProtocol": "tcp",
      "FromPort": 443,
      "ToPort": 443,
      "IpRanges": [
        {"CidrIp": "10.20.30.0/24", "Description": "internal load balancer subnet"}
      ]
    }
  ]
}

